{
  "loaded": "library",
  "tools": [
    {
      "description": "Create a new footprint (.kicad_mod) file from a pad layout description.",
      "name": "create_footprint"
    },
    {
      "description": "Edit the size, shape, or position of a pad in an existing .kicad_mod footprint file.",
      "name": "edit_footprint_pad"
    },
    {
      "description": "Register a local footprint library directory in the KiCAD global or project library table.",
      "name": "register_footprint_library"
    },
    {
      "description": "List all registered footprint libraries (global and optionally project-level).",
      "name": "list_footprint_libraries"
    },
    {
      "description": "Create a new KiCAD schematic symbol and append it to a .kicad_sym library file. Supports single-unit symbols (via `pins`) and multi-unit parts like dual/quad op-amps or gate banks (via `units` + optional `common_pins`). Each unit gets a rectangular body sized to its pins.",
      "name": "create_symbol"
    },
    {
      "description": "Delete a symbol definition from a .kicad_sym library file.",
      "name": "delete_symbol"
    },
    {
      "description": "List all symbol names defined in a .kicad_sym library file.",
      "name": "list_symbols_in_library"
    },
    {
      "description": "Register a .kicad_sym library file in the KiCAD global or project symbol table.",
      "name": "register_symbol_library"
    },
    {
      "description": "List all registered symbol libraries (global and optionally project-level).",
      "name": "list_symbol_libraries"
    },
    {
      "description": "Search for symbols across all registered libraries by name or keyword.",
      "name": "search_symbols"
    },
    {
      "description": "List all footprints in a specific registered footprint library (.pretty directory).",
      "name": "list_library_footprints"
    },
    {
      "description": "Return detailed information about a footprint: pad layout, courtyard, description.",
      "name": "get_footprint_info"
    },
    {
      "description": "Search for footprints across all registered libraries by name or keyword.",
      "name": "search_footprints"
    },
    {
      "description": "Return detailed information about a schematic symbol: pins, properties, description.",
      "name": "get_symbol_info"
    }
  ],
  "tools_added": 14
}

{
  "loaded": "sch_components",
  "tools": [
    {
      "description": "Create a new blank .kicad_sch schematic file.",
      "name": "create_schematic"
    },
    {
      "description": "Add a symbol from a KiCAD library to the schematic. The symbol is snapped to the 1.27mm schematic grid. Specify position in schematic mm coordinates.",
      "name": "add_schematic_component"
    },
    {
      "description": "Remove a symbol instance from the schematic by its reference designator.",
      "name": "delete_schematic_component"
    },
    {
      "description": "Update fields (Reference, Value, Footprint, custom properties) of a symbol instance.",
      "name": "edit_schematic_component"
    },
    {
      "description": "Get all properties, position, and pin locations for a symbol instance.",
      "name": "get_schematic_component"
    },
    {
      "description": "List all symbol instances in a schematic with their positions, values, footprints, and pin locations.",
      "name": "list_schematic_components"
    },
    {
      "description": "Move a symbol to a new position. Does NOT adjust connected wires.",
      "name": "move_schematic_component"
    },
    {
      "description": "Rotate a symbol by setting its absolute rotation angle (0/90/180/270).",
      "name": "rotate_schematic_component"
    },
    {
      "description": "Move a symbol and stretch/shrink connected wire stubs to preserve connections.",
      "name": "move_connected"
    },
    {
      "description": "Move all symbols within a bounding box by a given offset.",
      "name": "move_region"
    },
    {
      "description": "Run kicad-cli to auto-assign reference designators (R? → R1, U? → U1, etc.).",
      "name": "annotate_schematic"
    },
    {
      "description": "Get the exact schematic-space (X,Y) coordinates of every pin on a symbol, accounting for rotation and mirroring. Uses the canonical pin transform.",
      "name": "get_schematic_pin_locations"
    },
    {
      "description": "Get pin locations for multiple components in a single file read.",
      "name": "batch_get_schematic_pin_locations"
    },
    {
      "description": "Add a custom property (annotation) to a symbol instance in the schematic.",
      "name": "add_component_annotation"
    },
    {
      "description": "Add a group property to multiple components in the schematic.",
      "name": "group_components"
    },
    {
      "description": "Replace a component's lib_id with a new library symbol (swap the component type).",
      "name": "replace_component"
    },
    {
      "description": "Render the schematic to a PNG image (base64-encoded) via kicad-cli.",
      "name": "get_schematic_view"
    }
  ],
  "tools_added": 17
}

{
  "loaded": "sch_batch",
  "tools": [
    {
      "description": "Connect multiple component pins to a named net by adding net labels at each pin endpoint. Single file read → all labels inserted → single file write.",
      "name": "batch_connect_to_net"
    },
    {
      "description": "Delete multiple schematic items (wires, labels, junctions, components) by UUID or component reference designator — single file write.",
      "name": "batch_delete"
    },
    {
      "description": "Move multiple components by a uniform dx/dy offset in a single atomic file write.",
      "name": "bulk_move_schematic_components"
    },
    {
      "description": "Apply field updates (Value, Footprint, custom properties) to multiple components in a single atomic file write.",
      "name": "batch_edit_schematic_components"
    },
    {
      "description": "Delete multiple components by reference designator in a single atomic file write.",
      "name": "batch_delete_schematic_components"
    },
    {
      "description": "Add a wire stub and matching net label at a point to route a signal through a region without drawing a full wire path. Direction controls stub orientation.",
      "name": "connect_passthrough"
    },
    {
      "description": "Add a text annotation (non-net label) to the schematic at a given position.",
      "name": "add_schematic_text"
    },
    {
      "description": "Return a compact spatial summary of the schematic: component positions, bounding box, and optionally wire segments and label locations.",
      "name": "get_schematic_layout"
    },
    {
      "description": "Check all wire endpoints for floating ends (not connected to a pin, label, or another wire). Reports each floating endpoint with its coordinates.",
      "name": "validate_wire_connections"
    },
    {
      "description": "Check that every non-passive pin on every component has at least one wire or label connected. Reports unconnected pins with reference, pin number, and schematic position.",
      "name": "validate_component_connections"
    }
  ],
  "tools_added": 10
}

{
  "loaded": "sch_wiring",
  "tools": [
    {
      "description": "Add a wire segment between two points. The wire must be horizontal or vertical. T-junctions are automatically detected and junction dots inserted.",
      "name": "add_wire"
    },
    {
      "description": "Add multiple wire segments in a single file read/write cycle.",
      "name": "batch_add_wire"
    },
    {
      "description": "Delete a wire segment by its UUID, or by matching BOTH endpoints (all four of x1/y1/x2/y2, either direction). Fails without deleting anything when no wire matches.",
      "name": "delete_schematic_wire"
    },
    {
      "description": "Delete multiple wire segments in a single file read/write cycle.",
      "name": "batch_delete_schematic_wire"
    },
    {
      "description": "Split a wire at a given point, creating two wire segments and a junction.",
      "name": "split_wire_at_point"
    },
    {
      "description": "Add a net label to the schematic. Type can be 'net_label', 'global_label', or 'hierarchical_label'.",
      "name": "add_schematic_net_label"
    },
    {
      "description": "Delete a net label by net name and position.",
      "name": "delete_schematic_net_label"
    },
    {
      "description": "Rotate a net label to a new angle and update its justify direction accordingly.",
      "name": "rotate_schematic_label"
    },
    {
      "description": "Move all labels matching a net name by a given X/Y offset.",
      "name": "move_labels_by_offset"
    },
    {
      "description": "Rotate multiple labels by net name in a single file read/write cycle.",
      "name": "batch_rotate_labels"
    },
    {
      "description": "Add a power symbol (VCC, GND, etc.) to the schematic. Auto-numbers the internal #PWR reference.",
      "name": "add_power_symbol"
    },
    {
      "description": "Add a no-connect flag (X marker) to an unconnected pin endpoint.",
      "name": "add_no_connect"
    },
    {
      "description": "Remove a no-connect flag at a given position.",
      "name": "delete_no_connect"
    },
    {
      "description": "Delete multiple no-connect flags in a single file read/write cycle.",
      "name": "batch_delete_no_connect"
    },
    {
      "description": "Add a junction dot at a point where wires cross or T-intersect.",
      "name": "add_junction"
    },
    {
      "description": "Add multiple junction dots in a single file read/write cycle.",
      "name": "batch_add_junction"
    },
    {
      "description": "Connect a pin endpoint to a named net by adding a short wire stub and a net label.",
      "name": "connect_to_net"
    },
    {
      "description": "Connect two component pins by reference and pin number. Looks up pin coordinates automatically and routes a wire between them.",
      "name": "connect_pins"
    },
    {
      "description": "Connect two schematic points directly with a wire (auto-routes H+V segments). Use connect_pins if you have component references instead of coordinates.",
      "name": "add_schematic_connection"
    }
  ],
  "tools_added": 19
}
